+      detail = decodeURIComponent(rawSegment);
+    } catch {
+      detail = rawSegment;
+    }
+    detail = detail.replace(/\.[a-z0-9]{1,6}$/i, '').replace(/[-_]+/g, ' ').replace(/\s+/g, ' ').trim();
